package appeng.util; import appeng.api.config.Settings; import appeng.helpers.IConfigManager; import net.minecraft.nbt.CompoundNBT; import java.util.*; public class ConfigManager implements IConfigManager { public interface Listener { void changed(ConfigManager manager, Settings setting); } private final Map<Settings, Enum<?>> values = new EnumMap<>(Settings.class); public ConfigManager(Listener l) {} public <T extends Enum<T>> void registerSetting(Settings s, T v){ values.put(s,v); } @SuppressWarnings("unchecked") public <T extends Enum<T>> T getSetting(Settings s){ return (T) values.get(s); } public void readFromNBT(CompoundNBT nbt){} public void writeToNBT(CompoundNBT nbt){} }
